import { COMMON_WGSL } from './common.wgsl'
import { WATER_DDN_WGSL } from './water.wgsl'

/**
 * Ocean surface, forward port of the game's water.cfx (WaterPS) for the terrain water patches.
 *
 * Differences to the game shader:
 * - $WaterVolumeDDN is generated by an FFT simulation in the engine. Here it is replaced by
 *   waterDDN(), an analytic tiling wave sum with the same encoding (xyz normal, w height / 20)
 * - no screen space reflections, the env map is used only
 * - no subsurface scattering (ocean materials have a black diffuse, which disables it)
 */
export default /* wgsl */ `
${COMMON_WGSL}
${WATER_DDN_WGSL}

struct MaterialBlock {
  // ocean level, at or below DRY_WATER_HEIGHT the level has no ocean
  waterLevel           : f32,

  // xyz = specular color, w = gloss
  specularColor              : vec4f,
  tiling                     : f32,
  detailTiling               : f32,
  fresnelGloss               : f32,
  reflectionScale            : f32,
  reflectionBumpScale        : f32,
  refractionBumpScale        : f32,
  detailNormalsScale         : f32,
  normalsScale               : f32,
  gradientScale              : f32,
  heightScale                : f32,
  softIntersectionFactor     : f32,
  foamSoftIntersectionFactor : f32,
  foamAmount                 : f32,
  foamCrestAmount            : f32,
  foamTiling                 : f32,
  foamNormalScale            : f32,
  foamNormalFade             : f32,
  foamNormalSeparation       : f32,
  foamNormalTiling           : f32,
  foamTransitionSpeed        : f32,

  // ocean animation (mission <OceanAnimation>)
  windDirection : vec2f,
  windSpeed     : f32,
  wavesAmount   : f32,
  wavesSize     : f32,
  wavesSpeed    : f32,

  // foam scroll speed along the wind direction in meters per second
  foamScrollSpeed : f32,
};

struct InstanceBlock {
  transform:               mat4x4<f32>,

  // x: patch size (32, 64 etc.),
  // y: base factor (e.g. 2)
  // z: morphLod
  params1:                 vec4f,

  // x: fine layer color map index
  // y: coarse layer color map index
  // z: 1 = fine ready
  // w: 1 = coarse ready
  params2:                 vec4f,

  // x: this region's heightmap layer
  // y: +X neighbour, -1 if none
  // z: +Z neighbour, -1 if none
  // w: +X+Z neighbour, -1 if none
  params3:                 vec4f,

  // terrain only, see TerrainPatchMaterial
  regionParams:            vec4f,
  macroColor:              vec4f,
  heightUvTransform:       vec4f,
  heightUvTransformCoarse: vec4f,
};

// @private
@group(0) @binding(0) var<uniform> global: GlobalBlock;
// @private
@group(0) @binding(1) var<uniform> frame: FrameBlock;
// @private
@group(0) @binding(2) var<uniform> view: ViewBlock;

@group(0) @binding(3) var<uniform> object: ObjectBlock;
@group(0) @binding(4) var<uniform> material: MaterialBlock;

// @block global
// @private
@group(0) @binding(5) var envMap        : texture_cube<f32>;

// @block material
@group(1) @binding(0) var samplerClamp : sampler;
// @block material
@group(1) @binding(3) var samplerLinear : sampler;
// @block material
@group(1) @binding(4) var foamMap : texture_2d<f32>;
// @block material
@group(1) @binding(5) var foamNormalMap : texture_2d<f32>;
// @block material
@group(1) @binding(6) var glossMap : texture_2d<f32>;
// @block view
@group(1) @binding(7) var sceneDepthMap : texture_2d<f32>;
// @block view
@group(1) @binding(8) var sceneColorMap : texture_2d<f32>;

@group(2) @binding(0) var<storage, read> instances: array<InstanceBlock, 1>;

struct Varyings {
  @builtin(position) position : vec4f,
  @location(0) worldPos       : vec3f,
  // wave compression at crests, 0 = none, 1 = breaking (vPosWS.w in water.cfx)
  @location(2) crest          : f32,
  @location(3) @interpolate(flat) iid:  u32,
  // water level of the surface without waves
  @location(4) level          : f32,
};

struct VertexIn {
  @builtin(instance_index) instanceIndex: u32,
  @location(0) position:     vec3f,
  @location(1) texture:      vec2f,
};

@vertex
fn vsMain(input: VertexIn) -> Varyings {
  let instance = instances[input.instanceIndex];

  var worldPos = (instance.transform * object.modelMatrix * vec4f(input.position, 1.0));

  let patchSize = f32(instance.params1.x);
  let baseFactor = f32(instance.params1.y);
  let morphLod = f32(instance.params1.z);
  let morph = lod_morph(
    input.position.xy,         // raw grid position 0..64
    worldPos.xy,                // world space position
    view.cameraPosition.xy,
    patchSize,
    baseFactor,
    morphLod,
  );
  worldPos.x -= morph.offset.x;
  worldPos.y += morph.offset.y;

  // Ocean plane at the ocean level. Rivers and water volumes are separate meshes (WaterVolumeMaterial).
  let waterHeight = material.waterLevel;
  let amplitude = waveAmplitude();
  worldPos.z = waterHeight + waveSumZ(worldPos.xy, amplitude, frame.elapsedTime);

  var out : Varyings;
  out.position = view.projectionMatrix * view.viewMatrix * worldPos;
  out.worldPos = worldPos.xyz;
  out.level    = waterHeight;
  out.crest   = saturate(waveCompression(worldPos.xy, amplitude, frame.elapsedTime) * WAVE_COMPRESSION_SCALE);
  out.iid      = input.instanceIndex;
  return out;
}

// ── Fragment ──────────────────────────────────────────────────

@fragment
fn fsMain(in: Varyings) -> FragmentOutput {
  if (in.level <= DRY_WATER_HEIGHT) {
    // no ocean in this level (oceanLevel -1000)
    discard;
  }

  let mat     = material;
  let timeSec = frame.elapsedTime;
  // global.sunDirection points away from the sun, PerFrame_SunDirection of the original towards it
  let sunDir  = -normalize(global.sunDirection);

  let toEye   = view.cameraPosition - in.worldPos;
  let dist    = length(toEye);
  let vView   = toEye / dist;
  let side    = select(-1.0, 1.0, toEye.z >= 0.0); // -1 when looking from below the surface

  // ── Scene depth ───────────────────────────────────────────
  let screenSize   = vec2f(textureDimensions(sceneDepthMap, 0));
  let screenUv     = in.position.xy / screenSize;
  let surfaceDepth = linearizeDepthReversedZ(in.position.z, view.near, view.far);
  let sceneDepth   = loadSceneDepth(screenUv);

  // Water depth for the soft edge and foam. The game uses the view space depth difference, which grows at
  // grazing angles. Here the ray length behind the surface is projected onto the vertical axis, which is
  // the vertical drop to the rendered ground (terrain or objects) and does not depend on the view angle.
  // As the depth goes to 0 the water fades to the refracted scene, which hides the waterline on flat shores.
  let rayDepth   = max(sceneDepth - surfaceDepth, 0.0) * dist / max(surfaceDepth, 1e-3);
  let waterDepth = rayDepth * abs(vView.z);

  // Water edge softness, also fades out the refraction at the shore
  let softIntersect = saturate(mat.softIntersectionFactor * waterDepth);

  // Reduce gloss in distance (as in game, instead of a Toksvig factor for the wave normals)
  var gloss = mat.specularColor.w;
  gloss *= clamp(1.0 - dist / 250.0, 0.5, 1.0);

  // ── Texture coordinates ───────────────────────────────────
  // see WaterVS, don't touch the texture scales
  let animTime     = timeSec * 0.0025;
  let flowDir      = mat.windDirection;
  let vTranslation = (animTime * mat.windSpeed) * flowDir;
  let vTex         = in.worldPos.xy * 0.005;
  var baseTC       = vec4f(vTex.xy, vTex.yx * 2.0) * mat.tiling + vec4f(vTranslation, vTranslation.yx * 2.0);
  baseTC = vec4f(baseTC.xy, baseTC.zw * mat.detailTiling);

  // pixel footprints in texture space, waves above the nyquist limit are faded out
  let footprint       = uvFootprint(baseTC.xy);
  let footprintDetail = uvFootprint(baseTC.zw);

  // ── Normal ────────────────────────────────────────────────
  let vParalax  = getParalaxOffset(baseTC, footprint, vView, timeSec);
  var cGlossMap = textureSample(glossMap, samplerLinear, baseTC.xy * 0.05);
  var vNormal   = bumpGen(baseTC, footprint, footprintDetail, vParalax, timeSec);
  vNormal = normalize(mix(vec3f(0.0, 0.0, 1.0), vNormal, mat.reflectionBumpScale));

  // ── Foam ──────────────────────────────────────────────────
  cGlossMap = cGlossMap * 0.7 + 0.3;
  let cFoamThreshold = cGlossMap * 2.0 - 1.0; // reuse gloss for masking edges
  // The game scrolls the foam with OceanParams1.yz, which Lumberyard fills with the accumulated wind uv offset
  // instead of a direction, so the speed grows over time. Use an explicit speed along the wind instead.
  // The first layer moves with the wind, the second (larger scale) layer against it.
  let foamScroll   = flowDir * (timeSec * mat.foamScrollSpeed * 0.005 * mat.tiling); // meters -> baseTC units
  let foamUV       = (baseTC.xy + foamScroll) * mat.foamTiling;
  let foamNormalUV = (baseTC.xy + foamScroll) * mat.foamNormalTiling;
  var vFoamNormal  = decodeNormal(textureSample(foamNormalMap, samplerLinear, foamNormalUV).xy);

  // Add additional dynamic offset of a second layer foam
  let foamTime         = timeSec * 0.0005;
  let foamTranslation  = -(foamTime * mat.windSpeed) * flowDir * mat.foamTransitionSpeed - foamScroll * 0.6;
  let foamUV2          = 2.73 * baseTC.xy * mat.foamTiling + foamTranslation * mat.foamTiling;
  let foamNormalUV2    = 2.73 * baseTC.xy * mat.foamNormalTiling + foamTranslation * mat.foamNormalTiling;

  // Approximate foam sparking through mipmap bias
  var foamTexture = textureSampleBias(foamMap, samplerLinear, foamUV, -(1.0 - 4.0 * in.crest)).x;
  foamTexture += 0.5 * textureSampleBias(foamMap, samplerLinear, foamUV2, -(1.0 - 2.5 * in.crest)).x;
  vFoamNormal += 0.65 * decodeNormal(textureSample(foamNormalMap, samplerLinear, foamNormalUV2).xy);
  vFoamNormal = vec3f(vFoamNormal.xy * mat.foamNormalScale, vFoamNormal.z);

  var fFoam = foamTexture;
  let fFoamSoftIntersect = saturate(mat.foamSoftIntersectionFactor * waterDepth);

  // Foam 'areal noise function' to blend out edges in interesting way
  fFoam = fFoam * saturate(-fFoamSoftIntersect * (1.0 + cFoamThreshold.x) + fFoam);
  fFoam = fFoam * saturate(fFoamSoftIntersect - fFoamSoftIntersect * fFoamSoftIntersect);

  // Adding waves crests
  let crestTip    = saturate(in.crest * in.crest);
  let foamAtCrest = foamTexture * crestTip;
  fFoam = max(fFoam, (foamAtCrest * foamAtCrest + 0.5 * smoothstep(0.7, 0.9, foamAtCrest)) * mat.foamCrestAmount);

  // control radiance and quantity according to the sun glow
  fFoam *= luminance(global.sunColor.xyz);

  // Re-orient the foam normal onto the waves (https://blog.selfshadow.com/publications/blending-in-detail/)
  let foamArea = step(mat.foamNormalSeparation, fFoam * mat.foamNormalFade);
  vFoamNormal = mix(vec3f(0.0, 0.0, 1.0), vFoamNormal, foamArea);
  vFoamNormal = vec3f(-vFoamNormal.xy, vFoamNormal.z);
  vNormal.z += 1.0;
  vNormal = normalize(vNormal * dot(vNormal, vFoamNormal) - vFoamNormal * vNormal.z);

  // ── Reflection ────────────────────────────────────────────
  var cSpecularAcc = vec3f(0.0);
  if (dot(vView, vNormal) > 0.0) {
    let R = reflect(-vView, vNormal);
    cSpecularAcc = getReflectColor(envMap, samplerLinear, R, gloss) * mat.reflectionScale;
  }

  // internal reflections from below the surface
  let fNdotE = saturate(dot(vView, vNormal) * side);

  // ── Refraction ────────────────────────────────────────────
  let refrScale = saturate(1.0 - 0.15 * sqrt(saturate(surfaceDepth)));
  let refrTC    = vNormal.xy * mat.refractionBumpScale * softIntersect * refrScale;

  let depthRefr = vec3f(
    loadSceneDepth(clampScreenUv(screenUv + refrTC * 1.025)),
    loadSceneDepth(clampScreenUv(screenUv + refrTC)),
    loadSceneDepth(clampScreenUv(screenUv + refrTC * 0.985)),
  );
  // do not refract objects in front of the water surface
  let refrMask = select(vec3f(0.0), vec3f(1.0), vec3f(surfaceDepth) < depthRefr);
  var refractColor = vec3f(
    sampleSceneColor(screenUv + refrTC * refrMask.x * 1.025).x,
    sampleSceneColor(screenUv + refrTC * refrMask.y).y,
    sampleSceneColor(screenUv + refrTC * refrMask.z * 0.985).z,
  );

  // the scene behind was fogged by the fog pass, remove the in-scatter up to the water surface.
  // fog is applied again to the final color
  if (global.skipFog == 0u) {
    let fogTransmittance = getVolumetricFogDensity(in.worldPos);
    refractColor = max(refractColor - global.volumetricFogColorGradientBase.rgb * (1.0 - fogTransmittance), vec3f(0.0));
  }

  // ── Ocean fog ─────────────────────────────────────────────
  let oceanFog       = global.oceanFogColorDensity;
  let volumeDepth    = max(sceneDepth - surfaceDepth, 0.0);
  let volumeLength   = volumeDepth * dist / max(surfaceDepth, 1e-3);
  let waterVolumeFog = exp2(-oceanFog.w * volumeLength);
  refractColor = mix(oceanFog.rgb, refractColor, saturate(waterVolumeFog));

  // ── Sun specular ──────────────────────────────────────────
  let fNdotL = saturate(dot(vNormal, sunDir));
  cSpecularAcc += sunSpecular(fNdotL, vNormal, vView, sunDir);

  // ── Compose ───────────────────────────────────────────────
  const WATER_SPEC0 = 0.065;
  let fFresnel = WATER_SPEC0 + (1.0 - WATER_SPEC0) * pow(1.0 - fNdotE, 5.0) / (40.0 - 39.0 * mat.fresnelGloss);

  // Fake sun shadows: if sun opposing reflected surface normal, its darker
  let specLum    = dot(cSpecularAcc, vec3f(0.333));
  let fSunShadow = saturate(0.5 + specLum * specLum);

  let reflectionCoeff = saturate(fFresnel * softIntersect);
  let cWaterColor     = mix(refractColor, cSpecularAcc, reflectionCoeff);

  fFoam *= fSunShadow * softIntersect;
  let cFinal = cWaterColor * (1.0 - fFoam) + fFoam * mat.foamAmount;

  var out: FragmentOutput;
  out.color = applyFog(cFinal, 1.0, in.worldPos, view.cameraPosition);
  out.depth = surfaceDepth;

  let debug = global.debug;
  if (debug == DEBUG_GV_NORMAL || debug == DEBUG_GV_SHADE_NORMAL) {
    out.color = vec4f(vNormal * 0.5 + 0.5, 1.0);
  }
  return out;
}

// ── Scene helpers ─────────────────────────────────────────────

fn clampScreenUv(uv: vec2f) -> vec2f {
  return clamp(uv, vec2f(0.0), vec2f(1.0));
}

// linear scene depth, the sky (cleared to 0) is treated as far plane
fn loadSceneDepth(uv: vec2f) -> f32 {
  let dims  = vec2f(textureDimensions(sceneDepthMap, 0));
  let px    = vec2i(clamp(uv * dims, vec2f(0.0), dims - 1.0));
  let depth = textureLoad(sceneDepthMap, px, 0).r;
  return select(depth, view.far, depth <= 0.0);
}

fn sampleSceneColor(uv: vec2f) -> vec3f {
  return textureSampleLevel(sceneColorMap, samplerClamp, clampScreenUv(uv), 0.0).rgb;
}

fn uvFootprint(uv: vec2f) -> f32 {
  return max(length(dpdx(uv)), length(dpdy(uv)));
}

fn luminance(color: vec3f) -> f32 {
  return dot(color, vec3f(0.2126, 0.7152, 0.0722));
}

// two specular lobes for the ocean, see SunSpecular in water.cfx
fn sunSpecular(fNdotL: f32, vNormal: vec3f, vView: vec3f, sunDir: vec3f) -> vec3f {
  let gloss = material.specularColor.w;
  let k0 = 4.0 * gloss * 255.0;
  let k1 = 0.5 * gloss * 255.0;
  let n0 = k0 * ONE_OVER_TWO_PI + ONE_OVER_PI;
  let n1 = k1 * ONE_OVER_TWO_PI + ONE_OVER_PI;

  let R     = reflect(-vView, vNormal);
  let LdotR = saturate(dot(sunDir, R));
  let fSpec = n0 * pow(LdotR, k0) + n1 * pow(LdotR, k1);

  let cSpecular = material.specularColor.xyz * global.sunColor.xyz * global.sunColor.w;
  return fNdotL * fSpec * cSpecular;
}

// ── Water normals ─────────────────────────────────────────────

// $WaterVolumeDDN driven by the ocean animation
fn waterDDN(uv: vec2f, footprint: f32, timeSec: f32) -> vec4f {
  return waterDDNWaves(uv, footprint, timeSec, 0.6 * material.wavesSpeed, material.wavesAmount);
}

fn getParalaxOffset(baseTC: vec4f, footprint: f32, vView: vec3f, timeSec: f32) -> vec2f {
  let tcBaseVectorized = baseTC.xyxy * vec4f(0.25, 0.25, 1.0, 1.0);

  let lGradientScale = 0.5 * material.gradientScale;
  let lHeightScale   = 0.5 * material.heightScale;

  // Compute the height at this location
  var height = waterDDN(tcBaseVectorized.xy, footprint * 0.25, timeSec);
  var vParalax = vView.xy * (lHeightScale * height.w) + lGradientScale * height.xy;

  // Compute the height at the offset location
  height = waterDDN(tcBaseVectorized.zw + vParalax, footprint, timeSec);
  vParalax += vView.xy * (lHeightScale * height.w) + lGradientScale * height.xy;

  return vParalax;
}

fn bumpGen(baseTC: vec4f, footprint: f32, footprintDetail: f32, vParalaxOffset: vec2f, timeSec: f32) -> vec3f {
  // hi frequency
  let tcDetailBase = baseTC.zw + vParalaxOffset;
  // low frequency
  let tcBase0 = baseTC.xyxy * vec4f(0.25, 0.25, 1.0, 1.0);

  var bumpNormal = vec3f(waterDDN(tcDetailBase, footprintDetail, timeSec).xy * material.detailNormalsScale, 0.0);
  bumpNormal += waterDDN(tcBase0.xy + vParalaxOffset, footprint * 0.25, timeSec).xyz;
  bumpNormal += waterDDN(tcBase0.zw + vParalaxOffset, footprint, timeSec).xyz;
  bumpNormal = vec3f(bumpNormal.xy * material.normalsScale, bumpNormal.z);
  return normalize(bumpNormal);
}

// ── Geometry waves ────────────────────────────────────────────

const WAVE_COUNT : i32 = 6;

// Column layout: dirX, dirY, freqScale, ampScale
const waveTable = array<vec4f, 6>(
  vec4f( 0.831,  0.556, 1.00, 1.00),   // 0 — primary swell
  vec4f(-0.371,  0.928, 1.30, 0.60),   // 1 — secondary swell
  vec4f( 0.500,  0.866, 2.70, 0.25),   // 2 — mid chop
  vec4f(-0.866,  0.500, 3.10, 0.18),   // 3 — mid chop cross
  vec4f( 0.940, -0.342, 6.00, 0.08),   // 4 — fine ripple
  vec4f( 0.174,  0.985, 7.20, 0.06),   // 5 — fine ripple angled
);

// Speed scaling per band — fine ripples move slower relative to their freq.
const speedScale = array<f32, 6>(1.00, 0.80, 0.65, 0.60, 0.45, 0.40);

// ~420 m wavelength for the primary swell
const WAVE_BASE_FREQ : f32 = 0.015;
const WAVE_BASE_SPEED : f32 = 10.6;

fn waveAmplitude() -> f32 {
  return material.wavesSize * material.wavesAmount;
}

// The game measures how much the FFT displacement compresses the surface horizontally:
// saturate(-(dDispl.x + dDispl.y) * 0.035). For gerstner waves that is the steepness a * k * sin(phase),
// which peaks at the crests of steep waves and stays near zero for a calm ocean.
const WAVE_COMPRESSION_SCALE : f32 = 4.0;

fn waveCompression(pos: vec2f, amplitude: f32, timeSec: f32) -> f32 {
  var c = 0.0;
  let speed = WAVE_BASE_SPEED * material.wavesSpeed;
  for (var i = 0; i < WAVE_COUNT; i++) {
    let w     = waveTable[i];
    let freq  = WAVE_BASE_FREQ * w.z;
    let phase = freq * dot(w.xy, pos) - speed * speedScale[i] * freq * timeSec;
    c += amplitude * w.w * freq * sin(phase);
  }
  return c;
}

fn waveSumZ(pos: vec2f, amplitude: f32, timeSec: f32) -> f32 {
  var z = 0.0;
  let speed = WAVE_BASE_SPEED * material.wavesSpeed;
  for (var i = 0; i < WAVE_COUNT; i++) {
    let w     = waveTable[i];
    let freq  = WAVE_BASE_FREQ * w.z;
    let phase = freq * dot(w.xy, pos) - speed * speedScale[i] * freq * timeSec;
    z += amplitude * w.w * sin(phase);
  }
  return z;
}

// ── Terrain patch helpers ─────────────────────────────────────

struct MorphInfo {
  offset:   vec2f, // world space offset to apply to the vertex position for morphing
  t:        f32,
}

// gridPos is the raw vertex position in grid space, e.g. 0..64
// worldPos is the vertex position in world space
fn lod_morph(
  gridPos: vec2f,
  worldPos: vec2f,
  cameraPos: vec2f,
  patchSize: f32,
  baseFactor: f32, // e.g. 2, used on CPU for LOD selection (AABB nearest distance check)
  morphLod: f32,
) -> MorphInfo {
  let spacing     = exp2(morphLod);      // e.g. 1, 2, 4, 8 etc
  let sizeInWorld = patchSize * spacing; // e.g. 64, 128, 256 etc

  // HINT: rangeFactor of 1.0 is too tight
  let morphEnd     = sizeInWorld * baseFactor * 2.0;  // 2.0 hits right at the end of the patch
  let morphRange   = sizeInWorld * baseFactor * 0.3;

  let distance   = (distance(worldPos, cameraPos));
  let morphLerpK = 1.0 - clamp((morphEnd - distance)/morphRange, 0.0, 1.0);
  let morphLerp = fract(vec2f(gridPos.x, gridPos.y) * 0.5) * 2.0 * morphLerpK;

  var result: MorphInfo;
  result.offset   = morphLerp * spacing;
  result.t        = morphLerpK;

  return result;
}

// levels at or below this have no ocean (oceanLevel -1000)
const DRY_WATER_HEIGHT : f32 = 0.0;
`
